requireSession(matchId, sessionId) {
  this.match(matchId);
  const session = this.store.readSession(matchId, sessionId);
  if (!session) {
    throw new NotFoundError(`session ${sessionId} of match ${matchId} was not found`);
  }
  return session;
}

describeSession(matchId, session) {
  return {
